class TestWriting(unittest.TestCase):
    def test_a_value_is_written_with_its_discriminator(self) -> None:
        cases = [
            (True, '<boolean>1</boolean>'),
            (False, '<boolean>0</boolean>'),
            (1.0, '<double>1.0</double>'),
            (1.5, '<double>1.5</double>'),
            # NOTE (mristin):
            # An ``int`` is admitted next to a ``float``, and written free of
            # the fraction which a ``float`` carries.
            (1, '<double>1</double>'),
            ('a<b&c', '<string>a&lt;b&amp;c</string>'),
            (
                [0.0],
                '<array><data><value><double>0.0</double></value></data></array>'
            ),
            (
                {'k': 0.0},
                '<struct><member><name>k</name>'
                '<value><double>0.0</double></value></member></struct>'
            ),
        ]  # type: List[Tuple[aas_types.JsonValue, str]]

        for value, expected in cases:
            stream = io.StringIO()
            writer = aas_xmlcommon.Writer(stream)

            aas_xmlrpc.write_discriminator(value, writer)

            # NOTE (mristin):
            # The outermost element in no namespace undeclares the default
            # namespace, and the elements nested in it inherit that.
            self.assertEqual(
                expected.replace('>', ' xmlns="">', 1),
                stream.getvalue(),
                f"for the value {value!r}"
            )

    def test_the_path_of_a_failure_points_into_the_value(self) -> None:
        stream = io.StringIO()
        writer = aas_xmlcommon.Writer(stream)

        with self.assertRaises(
            aas_xmlcommon.SerializationException
        ) as context:
            aas_xmlrpc.write_struct_body(
                {'a b': [0, float('inf')]}, writer
            )

        self.assertEqual(
            "['a b'][1]", context.exception.path
        )

    def test_an_integer_too_large_for_a_float_is_not_written(self) -> None:
        # NOTE (mristin):
        # A <double> carries a JSON number, and a JSON number is a ``float``,
        # so an ``int`` which no ``float`` can hold exactly has no <double>
        # to be written as.
        for number in (2 ** 53 + 1, 10 ** 400):
            stream = io.StringIO()
            writer = aas_xmlcommon.Writer(stream)

            with self.assertRaises(
                aas_xmlcommon.SerializationException,
                msg=f"for the number {number}"
            ) as context:
                aas_xmlrpc.write_discriminator(number, writer)

            self.assertIn(
                'not exactly representable as a JSON number',
                context.exception.cause
            )

    def test_a_key_which_is_no_string_stops_the_path(self) -> None:
        stream = io.StringIO()
        writer = aas_xmlcommon.Writer(stream)

        with self.assertRaises(
            aas_xmlcommon.SerializationException
        ) as context:
            aas_xmlrpc.write_struct_body(
                cast(Mapping[str, Any], {1: 'no string key'}), writer
            )

        self.assertEqual('', context.exception.path)
        self.assertIn('but got a key of type', context.exception.cause)


